/**
 * Adaptive Feedback Experience Interfaces
 * Dynamic report generated by all engines
 */

import { z } from "zod";

// ============================================================================
// ADAPTIVE REPORT SECTION
// ============================================================================

export interface AdaptiveReportSection {
  id: string;
  type: "summary" | "strengths" | "weaknesses" | "progression" | "comparison" | "evolution" | "priorities" | "risks" | "objectives" | "action_plan";
  title: string;
  content: string;
  data: Record<string, unknown>;
  generatedBy: string[];
  confidence: number;
  priority: number;
  timestamp: Date;
}

export const AdaptiveReportSectionSchema = z.object({
  id: z.string(),
  type: z.enum(["summary", "strengths", "weaknesses", "progression", "comparison", "evolution", "priorities", "risks", "objectives", "action_plan"]),
  title: z.string(),
  content: z.string(),
  data: z.record(z.string(), z.any()),
  generatedBy: z.array(z.string()),
  confidence: z.number(),
  priority: z.number(),
  timestamp: z.date(),
});

// ============================================================================
// ADAPTIVE REPORT
// ============================================================================

export interface AdaptiveReport {
  id: string;
  sessionId: string;
  userId: string;
  sections: AdaptiveReportSection[];
  overallScore: number;
  overallConfidence: number;
  personalized: boolean;
  generatedBy: string[];
  timestamp: Date;
}

export const AdaptiveReportSchema = z.object({
  id: z.string(),
  sessionId: z.string(),
  userId: z.string(),
  sections: z.array(z.lazy(() => AdaptiveReportSectionSchema)),
  overallScore: z.number(),
  overallConfidence: z.number(),
  personalized: z.boolean(),
  generatedBy: z.array(z.string()),
  timestamp: z.date(),
});

// ============================================================================
// REPORT GENERATION CONTEXT
// ============================================================================

export interface ReportGenerationContext {
  sessionId: string;
  userId: string;
  sessionData: {
    duration: number;
    questionsAnswered: number;
    averageResponseTime: number;
    stressLevel: number;
    confidenceLevel: number;
    fatigueLevel: number;
  };
  historicalData: {
    previousSessions: number;
    averageScore: number;
    bestScore: number;
    trend: "improving" | "stable" | "declining";
    lastSessionDate?: Date;
  };
  userPreferences: {
    detailLevel: "brief" | "standard" | "detailed";
    focusAreas: string[];
    language: string;
  };
}

export const ReportGenerationContextSchema = z.object({
  sessionId: z.string(),
  userId: z.string(),
  sessionData: z.object({
    duration: z.number(),
    questionsAnswered: z.number(),
    averageResponseTime: z.number(),
    stressLevel: z.number(),
    confidenceLevel: z.number(),
    fatigueLevel: z.number(),
  }),
  historicalData: z.object({
    previousSessions: z.number(),
    averageScore: z.number(),
    bestScore: z.number(),
    trend: z.enum(["improving", "stable", "declining"]),
    lastSessionDate: z.date().optional(),
  }),
  userPreferences: z.object({
    detailLevel: z.enum(["brief", "standard", "detailed"]),
    focusAreas: z.array(z.string()),
    language: z.string(),
  }),
});

// ============================================================================
// ADAPTIVE FEEDBACK CONFIG
// ============================================================================

export interface AdaptiveFeedbackConfig {
  includeComparison: boolean;
  includeEvolution: boolean;
  includeActionPlan: boolean;
  includeRisks: boolean;
  personalizationEnabled: boolean;
  engineWeights: Record<string, number>;
  minConfidenceThreshold: number;
  maxSections: number;
}

export const AdaptiveFeedbackConfigSchema = z.object({
  includeComparison: z.boolean(),
  includeEvolution: z.boolean(),
  includeActionPlan: z.boolean(),
  includeRisks: z.boolean(),
  personalizationEnabled: z.boolean(),
  engineWeights: z.record(z.string(), z.number()),
  minConfidenceThreshold: z.number(),
  maxSections: z.number(),
});

export const defaultAdaptiveFeedbackConfig: AdaptiveFeedbackConfig = {
  includeComparison: true,
  includeEvolution: true,
  includeActionPlan: true,
  includeRisks: true,
  personalizationEnabled: true,
  engineWeights: {
    CareerProfile: 0.15,
    ProgressEngine: 0.12,
    Confidence: 0.10,
    Employability: 0.12,
    WeaknessDetector: 0.13,
    RecommendationEngine: 0.12,
    LearningPath: 0.10,
    Diagnostic: 0.08,
    ProfessionalReport: 0.08,
  },
  minConfidenceThreshold: 0.5,
  maxSections: 10,
};
